// ======================= SETTINGS — fill these in once =======================
// Both agents in this workflow read these values. Don't share this workflow after adding your keys.
return [{
  json: {
    FREELANCER_TOKEN: '',        // accounts.freelancer.com/settings/develop → Personal Access Token
    FREELANCER_TOKEN_DATE: '',   // day you generated it, e.g. '2026-11-04' (tokens last 30 days)
    GEMINI_API_KEY: '',          // aistudio.google.com → Get API key (free)
    GEMINI_MODEL: 'gemini-flash-latest',
    TELEGRAM_BOT_TOKEN: '',      // from @BotFather in Telegram
    TELEGRAM_CHAT_ID: '',        // your own chat id (see SETUP.md)

    // Customer service assistant (read-only: drafts replies, never sends)
    MAX_THREADS_PER_RUN: 5,      // keeps you inside the free AI limits

    // Won projects → Upwork post
    FREELANCER_FEE_PERCENT: 10,  // what Freelancer.com takes from your earnings
    TARGET_PROFIT_PERCENT: 40,   // share of your net earnings you want to keep as profit
    INR_PER_USD: 88,             // used to show the Upwork budget in USD; update now and then

    // Describe your business. The agent only says things that are true according to this.
    BUSINESS_PROFILE: `
You reply to clients on Freelancer.com on behalf of the account owner, writing in first person as them.
Services offered: digital marketing (Meta Ads, SEO, Instagram), website design & development, graphic design, content writing.
Typical process: requirements call/chat -> plan within 24h -> work in milestones -> weekly updates -> revisions -> delivery.
Revisions: up to 2 rounds included unless the project says otherwise.
Working hours: Mon-Sat, 10am-7pm IST. Replies within a few hours.
Tone: friendly, confident, short (2-5 sentences), professional English, no emojis overload, no long greetings.
`,
  },
}];

// Freelancer.com customer service assistant for n8n (Code node, "Run Once for All Items").
// READ-ONLY: it reads your Freelancer messages, drafts a reply with Gemini, and sends the draft to you on Telegram.
// It never sends anything on Freelancer; you copy the reply and send it yourself.
// Runs every 2 minutes. Settings come from the Settings node.
//
// NOTE: state (which messages were already drafted) is only saved when the workflow is Published/Active,
// not on manual "Execute" test runs.

const CONFIG = $('Settings').first().json;
const BUSINESS_PROFILE = CONFIG.BUSINESS_PROFILE;

const RULES = `
Hard rules:
- Never agree to or propose prices, discounts, refunds, extra payments, deadline changes, or new scope. Mark these needs_owner.
- Never mention subcontracting, other freelancers, other platforms, or Upwork.
- Never ask the client to move off Freelancer.com (no email, phone, WhatsApp, external payment). If the client asks for that, needs_owner.
- If the client is upset, complaining, or threatening a dispute/review, mark needs_owner.
- Never invent project status, files, dates, or results. If you don't know, say you'll check and update them shortly, and mark needs_owner.
- Routine = greetings, thanks, clarifying questions about requirements, asking for materials (logos, logins, references), explaining the general process.

Return ONLY JSON: {"reply": "<message to send>", "category": "routine" | "needs_owner", "reason": "<why, one short line>"}
`;

const FL = 'https://www.freelancer.com/api';

const missing = ['FREELANCER_TOKEN', 'GEMINI_API_KEY', 'TELEGRAM_BOT_TOKEN', 'TELEGRAM_CHAT_ID'].filter((k) => !CONFIG[k]);
if (missing.length) throw new Error(`Fill in these values in the Settings node: ${missing.join(', ')}`);

const state = $getWorkflowStaticData('node');
state.seen ??= {};       // threadId -> marker of last message handled

const parse = (r) => (typeof r === 'string' ? JSON.parse(r) : r);

const TOKEN_HELP = 'Generate a new Personal Access Token at https://accounts.freelancer.com/settings/develop and paste it into the Settings node.';
const explain = (e) => {
  const code = String(e.httpCode ?? e.response?.status ?? e.statusCode);
  if (code === '401') return `Freelancer token expired or invalid (401). ${TOKEN_HELP}`;
  if (code === '403') return 'Freelancer refused access (403): the token may not include messaging permission (fln:messaging), or your account needs identity verification.';
  return e.message;
};

const flGet = async (path) =>
  parse(await this.helpers.httpRequest({ method: 'GET', url: FL + path, headers: { 'freelancer-oauth-v1': CONFIG.FREELANCER_TOKEN } })).result;

const tgSay = async (text) =>
  this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${CONFIG.TELEGRAM_BOT_TOKEN}/sendMessage`,
    body: { chat_id: CONFIG.TELEGRAM_CHAT_ID, text: text.slice(0, 4000), disable_web_page_preview: true },
    json: true,
  });

const log = { drafted: 0, errors: [] };

// Remind you before the 30-day token runs out (once a day from day 26).
if (CONFIG.FREELANCER_TOKEN_DATE) {
  const age = Math.floor((Date.now() - new Date(CONFIG.FREELANCER_TOKEN_DATE).getTime()) / 86400000);
  const today = new Date().toISOString().slice(0, 10);
  if (age >= 26 && state.tokenWarnedOn !== today) {
    state.tokenWarnedOn = today;
    await tgSay(`🔑 Your Freelancer token is ${age} days old and stops working at 30 days. ${TOKEN_HELP} Also update FREELANCER_TOKEN_DATE.`);
  }
}

// ---------- Read Freelancer conversations ----------
let threads;
try {
  state.myId ??= (await flGet('/users/0.1/self/')).id;
  threads = (await flGet('/messages/0.1/threads/?last_message=true&limit=20')).threads || [];
} catch (e) {
  log.errors.push(explain(e));
  threads = [];
}

const markerOf = (t) => String(t.message?.id ?? t.thread?.message?.id ?? t.time_updated ?? '');

if (!state.initialized && !log.errors.length) {
  // First run: don't draft replies for old conversations, just remember where we are.
  for (const t of threads) state.seen[t.id] = markerOf(t);
  state.initialized = true;
  await tgSay(`🤖 Customer service assistant is live (read-only). Watching ${threads.length} Freelancer conversations. New client messages will arrive here with a suggested reply.`);
  return [{ json: { status: 'initialized', threads: threads.length } }];
}

const changed = threads.filter((t) => markerOf(t) && state.seen[t.id] !== markerOf(t));
for (const t of changed.slice(0, CONFIG.MAX_THREADS_PER_RUN)) {
  try {
    const marker = markerOf(t);
    const msgs = ((await flGet(`/messages/0.1/messages/?threads[]=${t.id}&limit=10`)).messages || [])
      .sort((a, b) => (a.time_created ?? 0) - (b.time_created ?? 0));
    const last = msgs[msgs.length - 1];
    state.seen[t.id] = marker;
    if (!last || String(last.from_user) === String(state.myId)) continue; // you already replied

    let project = '';
    const ctx = t.thread?.context ?? t.context;
    if (ctx?.type === 'project' && ctx.id) {
      try {
        const p = await flGet(`/projects/0.1/projects/${ctx.id}/`);
        project = `Project: ${p.title}\nBudget: ${p.budget?.minimum ?? '?'}-${p.budget?.maximum ?? '?'} ${p.currency?.code ?? ''}\nDescription: ${(p.description || '').slice(0, 1500)}`;
      } catch (e) { /* project details are optional */ }
    }

    const transcript = msgs.map((m) => `${String(m.from_user) === String(state.myId) ? 'You' : 'Client'}: ${m.message}`).join('\n');

    const ai = parse(await this.helpers.httpRequest({
      method: 'POST',
      url: `https://generativelanguage.googleapis.com/v1beta/models/${CONFIG.GEMINI_MODEL}:generateContent`,
      headers: { 'x-goog-api-key': CONFIG.GEMINI_API_KEY },
      json: true,
      body: {
        systemInstruction: { parts: [{ text: BUSINESS_PROFILE + RULES }] },
        contents: [{ role: 'user', parts: [{ text: `${project}\n\nConversation (latest last):\n${transcript}\n\nWrite the next reply.` }] }],
        generationConfig: { responseMimeType: 'application/json', temperature: 0.4 },
      },
    }));
    const raw = ai.candidates?.[0]?.content?.parts?.map((p) => p.text).join('') ?? '';
    let out;
    try { out = JSON.parse(raw); } catch { out = { reply: raw, category: 'needs_owner', reason: 'AI answer was not in the expected format' }; }
    const reply = String(out.reply || '').trim();
    if (!reply) throw new Error('AI returned an empty reply');

    const flag = out.category === 'routine' ? '🟢 Routine' : `⚠️ Check before sending: ${out.reason || ''}`;
    await tgSay(
      `💬 New client message on Freelancer\n${project ? project.split('\n')[0] + '\n' : ''}` +
      `Open chat: https://www.freelancer.com/messages/thread/${t.id}\n\nClient: ${last.message.slice(0, 1200)}\n\n${flag}\n🤖 Suggested reply is in the next message.`,
    );
    await tgSay(reply); // separate message so it's one tap to copy
    log.drafted++;
  } catch (e) {
    log.errors.push(`Thread ${t.id}: ${explain(e)}`);
  }
}

// Tell you about errors, at most every 30 minutes.
if (log.errors.length && Date.now() - (state.lastErrorAt || 0) > 30 * 60 * 1000) {
  state.lastErrorAt = Date.now();
  await tgSay(`⚠️ Assistant problem:\n${log.errors.slice(0, 5).join('\n')}`);
}

return [{ json: { ...log, newConversations: changed.length } }];

// Won projects → ready-to-paste Upwork job post (n8n Code node, "Run Once for All Items").
// Checks every 10 minutes for Freelancer bids that were awarded to you. For each new one it sends you on Telegram:
//   1. A deal summary: what you earn, the most you can pay on Upwork and still hit your profit target, what to ask the client.
//   2. An anonymized Upwork job post to copy and paste. No client name, brand, URL or Freelancer mention.

const CONFIG = $('Settings').first().json;
const state = $getWorkflowStaticData('node');

if (Date.now() - (state.lastCheck || 0) < 10 * 60 * 1000) return [{ json: { skipped: 'checked less than 10 minutes ago' } }];
state.lastCheck = Date.now();

const missing = ['FREELANCER_TOKEN', 'GEMINI_API_KEY', 'TELEGRAM_BOT_TOKEN', 'TELEGRAM_CHAT_ID'].filter((k) => !CONFIG[k]);
if (missing.length) throw new Error(`Fill in these values in the Settings node: ${missing.join(', ')}`);

state.seenBids ??= {};

const FL = 'https://www.freelancer.com/api';
const parse = (r) => (typeof r === 'string' ? JSON.parse(r) : r);
const flGet = async (path) =>
  parse(await this.helpers.httpRequest({ method: 'GET', url: FL + path, headers: { 'freelancer-oauth-v1': CONFIG.FREELANCER_TOKEN } })).result;
const tgSay = async (text) =>
  this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${CONFIG.TELEGRAM_BOT_TOKEN}/sendMessage`,
    body: { chat_id: CONFIG.TELEGRAM_CHAT_ID, text: text.slice(0, 4000) },
    json: true,
  });

const explain = (e) => {
  const code = String(e.httpCode ?? e.response?.status ?? e.statusCode);
  if (code === '401') return 'Freelancer token expired or invalid (401). Generate a new one at https://accounts.freelancer.com/settings/develop';
  if (code === '403') return 'Freelancer refused access to your bids (403): the token may not include project permission (fln:project_manage).';
  return e.message;
};

let bids;
try {
  state.myId ??= (await flGet('/users/0.1/self/')).id;
  const since = Math.floor(Date.now() / 1000) - 90 * 86400;
  bids = (await flGet(`/projects/0.1/bids/?bidders[]=${state.myId}&award_statuses[]=awarded&from_time=${since}&limit=50`)).bids || [];
} catch (e) {
  if (Date.now() - (state.lastErrorAt || 0) > 6 * 3600 * 1000) {
    state.lastErrorAt = Date.now();
    await tgSay(`⚠️ Won-projects check failed: ${explain(e)}`);
  }
  return [{ json: { error: explain(e) } }];
}

if (!state.initialized) {
  // First run: don't post about projects you already won before turning this on.
  for (const b of bids) state.seenBids[b.id] = true;
  state.initialized = true;
  await tgSay(`🏆 Won-project watcher is live. ${bids.length} earlier awarded project(s) skipped. New wins will arrive here with an Upwork post ready to paste.`);
  return [{ json: { status: 'initialized', skipped: bids.length } }];
}

const fresh = bids.filter((b) => !state.seenBids[b.id]);
const done = [];
for (const b of fresh.slice(0, 3)) {
  try {
    const p = await flGet(`/projects/0.1/projects/${b.project_id}/?full_description=true&job_details=true`);
    const cur = p.currency?.code || '';
    const sign = p.currency?.sign || '';
    const earn = Number(b.amount) || 0;
    const net = earn * (1 - CONFIG.FREELANCER_FEE_PERCENT / 100);
    const maxHire = net * (1 - CONFIG.TARGET_PROFIT_PERCENT / 100);
    const usd = cur === 'USD' ? maxHire : cur === 'INR' ? maxHire / CONFIG.INR_PER_USD : null;
    const money = (n) => `${sign}${Math.round(n).toLocaleString('en-IN')} ${cur}`;
    const skills = (p.jobs || []).map((j) => j.name).filter(Boolean);

    const ai = parse(await this.helpers.httpRequest({
      method: 'POST',
      url: `https://generativelanguage.googleapis.com/v1beta/models/${CONFIG.GEMINI_MODEL}:generateContent`,
      headers: { 'x-goog-api-key': CONFIG.GEMINI_API_KEY },
      json: true,
      body: {
        systemInstruction: { parts: [{ text: `You turn a client's project brief into an Upwork job post for hiring a freelancer.
Rules:
- Remove every client identifier: company/brand names, people's names, website URLs, emails, phone numbers, social handles. Describe the business generically (e.g. "a premium Indian home-décor brand").
- Never mention Freelancer.com, reselling, or subcontracting.
- Keep the real scope and deliverables. Make goals realistic (no guaranteed results).
- Ask applicants for relevant samples and a fixed price.
- Also list the materials/info you must collect from the client before work starts.
Return ONLY JSON: {"title": "...", "description": "...", "skills": ["..."], "duration": "...", "client_questions": ["..."]}` }] },
        contents: [{ role: 'user', parts: [{ text: `Project title: ${p.title}\nSkills: ${skills.join(', ')}\nBrief:\n${(p.description || '').slice(0, 5000)}` }] }],
        generationConfig: { responseMimeType: 'application/json', temperature: 0.4 },
      },
    }));
    const raw = ai.candidates?.[0]?.content?.parts?.map((x) => x.text).join('') ?? '';
    const post = JSON.parse(raw);

    const budgetLine = usd != null ? `$${Math.floor(usd)} (≈ ${money(maxHire)})` : money(maxHire);
    const tooLow = usd != null && usd < 25;

    await tgSay(
      `🏆 You won: ${p.title}\nhttps://www.freelancer.com/projects/${p.seo_url || p.id}\n\n` +
      `💰 You get: ${money(earn)} → after ${CONFIG.FREELANCER_FEE_PERCENT}% fee: ${money(net)}\n` +
      `👷 Pay at most on Upwork: ${budgetLine} to keep ${CONFIG.TARGET_PROFIT_PERCENT}% profit\n` +
      (tooLow ? '⚠️ This budget is very low for Upwork. Consider doing it yourself, renegotiating scope, or a cheaper freelancer.\n' : '') +
      `\n📋 Ask the client for:\n${(post.client_questions || []).map((q) => `• ${q}`).join('\n')}\n\nThe Upwork post is in the next message. Copy it into Upwork → Post a job.`,
    );
    await tgSay(
      `${post.title}\n\n${post.description}\n\nSkills: ${(post.skills || skills).join(', ')}\nDuration: ${post.duration || 'see description'}\nBudget: fixed price, up to ${usd != null ? '$' + Math.floor(usd) : money(maxHire)}`,
    );
    state.seenBids[b.id] = true;
    done.push(p.title);
  } catch (e) {
    await tgSay(`⚠️ Couldn't prepare the Upwork post for project ${b.project_id}: ${explain(e)}. I'll retry in 10 minutes.`);
  }
}

return [{ json: { newWins: done } }];
